// URLs already saved in Notion (finds the Job URL column whatever n8n calls it)
const existing = new Set();
for (const item of $input.all()) {
  const j = item.json;
  for (const key of Object.keys(j)) {
    if (key.toLowerCase().replace(/[^a-z]/g, '').includes('joburl') && j[key]) {
      existing.add(String(j[key]).trim());
    }
  }
}

// Jobs fetched from TheirStack today that passed the filter (jobs with a drop reason are not saved here)
const jobs = $('Pre-Score Filter').all().filter(i => !i.json.drop_reason);

const seen = new Set();
const fresh = [];
for (const item of jobs) {
  const url = (item.json.url || '').trim();
  if (!url || existing.has(url) || seen.has(url)) continue;
  seen.add(url);
  fresh.push({ json: item.json });
}
return fresh;

const DE = [' und ', ' die ', ' der ', ' das ', ' wir ', ' für ', ' mit ', ' sie ', ' du ', ' dein', 'aufgaben', 'kenntnisse', ' bei '];
const EN = [' and ', ' the ', ' you ', ' we ', ' with ', ' for ', ' your ', ' our ', ' will ', 'experience'];
const count = (t, arr) => arr.reduce((n, k) => n + t.split(k).length - 1, 0);

// A German posting is still kept when it asks for good or fluent English
const ENGLISH_WANTED = /(flie(ß|ss)end\w*|verhandlungssicher\w*|sehr gute\w*|gute\w*|exzellente\w*|ausgezeichnete\w*|fluent|business fluent)[^.\n]{0,40}(englisch\w*|english)|(englisch\w*|english)[^.\n]{0,40}(flie(ß|ss)end\w*|verhandlungssicher\w*|fluent|in wort und schrift)|englisch in wort und schrift/;

return $input.all().map(item => {
  const j = item.json;
  const fullText = String(j.description || '').toLowerCase();
  const full = ' ' + fullText.slice(0, 3000) + ' ';
  const isGerman = count(full, DE) > count(full, EN);
  const wantsEnglish = ENGLISH_WANTED.test(fullText);
  return { j, keep: !isGerman || wantsEnglish, germanPosting: isGerman };
}).filter(x => x.keep).map(({ j, germanPosting }) => {
  const co = j.company_object || {};
  const rawEmp = co.employee_count ?? j.employee_count ?? null;
  const employees = (rawEmp !== null && rawEmp !== '' && !isNaN(Number(rawEmp))) ? Number(rawEmp) : null;
  const workType = j.remote ? 'Remote' : j.hybrid ? 'Hybrid' : (j.location || j.long_location ? 'On-site' : 'Unknown');
  return {
    json: {
      job_id: String(j.id),
      title: j.job_title || '',
      company: j.company || '',
      company_domain: j.company_domain || '',
      url: j.url || '',
      location: j.long_location || j.location || '',
      remote: !!j.remote,
      hybrid: !!j.hybrid,
      work_type: workType,
      employees: employees,
      auto_skip: employees !== null && employees < 50,
      german_posting: germanPosting,
      seniority: j.seniority || '',
      date_posted: j.date_posted || '',
      description: String(j.description || '').slice(0, 1900)
    }
  };
});

const norm = s => String(s || '').trim().toLowerCase();

// Companies already in Notion
const existing = new Set();
for (const item of $input.all()) {
  const j = item.json;
  for (const key of Object.keys(j)) {
    if (key.toLowerCase().includes('name') && j[key]) existing.add(norm(j[key]));
  }
}

// Companies in today's new jobs
const jobs = $('Find New Jobs').all();
const missing = new Map();
for (const item of jobs) {
  const name = String(item.json.company || '').trim();
  const k = norm(name);
  if (name && !existing.has(k) && !missing.has(k)) missing.set(k, name);
}

// Always return something, so the workflow keeps going
if (missing.size === 0) return [{ json: { name: '', skip: true } }];
return [...missing.values()].map(name => ({ json: { name, skip: false } }));

const norm = s => String(s || '').trim().toLowerCase();

// company name -> Notion page id
const map = new Map();
for (const item of $input.all()) {
  const j = item.json;
  const nameKey = Object.keys(j).find(k => k.toLowerCase().includes('name'));
  if (nameKey && j[nameKey] && j.id) map.set(norm(j[nameKey]), j.id);
}

// today's new jobs, each with its company page id, one per URL
const seen = new Set();
const out = [];
for (const item of $('Find New Jobs').all()) {
  const url = String(item.json.url || '').trim();
  if (!url || seen.has(url)) continue;
  seen.add(url);
  out.push({ json: { ...item.json, company_id: map.get(norm(item.json.company)) || null } });
}
return out;

// Credits: each returned job costs 1 credit. Free plan = 200 per month.
// 6 jobs per day is about 180 per month. Change the numbers here only.
const LIMITS = { de_onsite: 2, de_hybrid: 1, de_remote: 1, eu_remote: 1, us_remote: 1 };

const TITLES = [
  'business analyst', 'junior business analyst', 'IT business analyst',
  'project coordinator', 'IT project coordinator', 'project assistant',
  'PMO analyst', 'PMO'
];

const EU = ['NL','IE','PT','ES','FR','AT','PL','BE','LU','IT','SE','DK','FI','CZ'];

// Phrases that exclude a job inside TheirStack, so those jobs cost no credits
const EXCLUDE = '(?i)(authori[sz]ed to work in the (U\\.?S\\.?|United States)|legally authori[sz]ed to work|eligible to work in the (U\\.?S\\.?|United States)|work authori[sz]ation|(no|without|not) (visa )?sponsorship|(U\\.?S\\.?|United States) (citizen|citizenship|resident)|security clearance)';

const make = (name, countries, workplace, limit) => ({
  json: {
    name,
    body: {
      job_title_or: TITLES,
      job_country_code_or: countries,
      workplace_types_or: [workplace],
      job_description_pattern_not: [EXCLUDE],
      posted_at_max_age_days: 1,
      limit
    }
  }
});

return [
  make('DE on-site', ['DE'], 'on_site', LIMITS.de_onsite),
  make('DE hybrid',  ['DE'], 'hybrid',  LIMITS.de_hybrid),
  make('DE remote',  ['DE'], 'remote',  LIMITS.de_remote),
  make('EU remote',  EU,     'remote',  LIMITS.eu_remote),
  make('US remote',  ['US'], 'remote',  LIMITS.us_remote)
];

const TITLE_STRONG = ['business analyst', 'it business analyst', 'junior business analyst', 'project coordinator', 'pmo', 'project assistant', 'project support', 'functional analyst', 'test analyst', 'junior project manager'];
const TITLE_WEAK = ['analyst', 'coordinator', 'project', 'assistant', 'business'];
const SKILLS = ['sql', 'jira', 'confluence', 'uat', 'user acceptance', 'requirements', 'stakeholder', 'process', 'excel', 'power bi', 'agile', 'scrum', 'documentation', 'reporting', 'erp', 'sap', 'test', 'data analysis', 'project management', 'user stories', 'workshop', 'compliance', 'finance', 'ifrs'];
const GERMAN_NEEDED = ['german required', 'fluent german', 'fluency in german', 'german language', 'native german', 'german c1', 'german (c1', 'german is a must', 'proficiency in german', 'good command of german', 'deutschkenntnisse', 'german speaking'];
const US_AUTH = ['authorized to work in the u', 'authorised to work in the u', 'legally authorized to work', 'eligible to work in the u', 'work authorization', 'work authorisation', 'no sponsorship', 'without sponsorship', 'not provide sponsorship', 'u.s. citizen', 'us citizen', 'security clearance'];

const MIN_TRASH_SCORE = 30; // below this a dropped job is not worth keeping in Trash
const MAX_TRASH = 20;       // at most this many dropped jobs go to Trash per run

const passed = [];
const dropped = [];
for (const item of $input.all()) {
  const j = item.json;
  const title = String(j.title || '').toLowerCase();
  const desc = String(j.description || '').toLowerCase();
  const loc = String(j.location || '').toLowerCase();

  // Hard exclusion: US work authorization phrases (discarded, not saved)
  if (US_AUTH.some(p => desc.includes(p))) continue;

  // Location rule: Berlin = any type, everywhere else = remote only (discarded, not saved)
  const isBerlin = loc.includes('berlin');
  const isRemote = !!j.remote || /remote|home office|homeoffice/.test(loc);
  if (!isBerlin && !isRemote) continue;

  let score = 0;

  // Title (30)
  if (TITLE_STRONG.some(k => title.includes(k))) score += 30;
  else if (TITLE_WEAK.some(k => title.includes(k))) score += 15;

  // Skills (25): 5 points per match
  score += Math.min(25, SKILLS.filter(k => desc.includes(k)).length * 5);

  // Location (15): every job that reaches this point is Berlin or remote
  score += 15;

  // German not required (10)
  if (!GERMAN_NEEDED.some(k => desc.includes(k))) score += 10;

  // Seniority (5, or -15 for senior)
  const senior = ['senior', 'staff', 'c_level'].includes(String(j.seniority || '').toLowerCase()) || /senior|principal|head of|director|lead\b/.test(title);
  score += senior ? -15 : 5;

  // Contact points (15) are added later in Workflow 3
  if (score < MIN_TRASH_SCORE) continue; // too weak even for Trash (discarded)

  if (j.auto_skip) dropped.push({ json: { ...j, quick_score: score, drop_reason: 'Under 50 employees' } });
  else if (score > 50) passed.push({ json: { ...j, quick_score: score, drop_reason: '' } });
  else dropped.push({ json: { ...j, quick_score: score, drop_reason: 'Low pre-score' } });
}

dropped.sort((a, b) => b.json.quick_score - a.json.quick_score);
return [...passed, ...dropped.slice(0, MAX_TRASH)];

const norm = (u) => String(u || '').split('?')[0].replace(/\/+$/, '').toLowerCase();

// Jobs that already exist in Trash or in Jobs are never created again
const known = new Set();
for (const r of $('Get Trash Rows').all()) { const u = norm(r.json.property_url); if (u) known.add(u); }
for (const r of $('Get Existing Jobs1').all()) { const u = norm(r.json.property_job_url); if (u) known.add(u); }

// Jobs the filter kept back (under 50 employees or low pre-score)
const jobs = $('Pre-Score Filter').all().map(i => i.json).filter(j => j.drop_reason);

const out = [];
for (const j of jobs) {
  const url = j.url || '';
  const key = norm(url);
  if (!key || known.has(key)) continue;
  known.add(key);

  out.push({ json: {
    name: j.title || '',
    company: j.company || '',
    location: j.location || '',
    work_type: j.work_type === 'Unknown' ? '' : (j.work_type || ''),
    employees: j.employees == null ? 0 : j.employees, // 0 = unknown
    url: url,
    source: 'TheirStack',
    reason: j.drop_reason,
    pre_score: j.quick_score == null ? 0 : j.quick_score,
    description: String(j.description || '').slice(0, 1990)
  } });
}
return out;
